import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import type { Tab } from './tabs';

/**
 * Starlight 0.42 labels an autogenerated folder with the directory name
 * (`engine`, `app`) and does not read `sidebar.label` as the group name.
 * This builds each tab from `src/content/docs/` instead: a directory index
 * contributes the group label (`sidebar.label`) and the first link (`title`).
 * Page order still comes from `sidebar.order`.
 */
const docsRoot = fileURLToPath(new URL('./content/docs/', import.meta.url));

type Frontmatter = {
	title: string;
	label?: string;
	order: number;
};

type Ranked = {
	order: number;
	slug: string;
	isIndex: boolean;
	item: SidebarItem;
};

type SidebarItem =
	| { slug: string; label?: string }
	| { label: string; items: SidebarItem[] };

function readFrontmatter(filePath: string): Frontmatter {
	const raw = fs.readFileSync(filePath, 'utf8');
	const match = raw.match(/^---\r?\n([\s\S]*?)\r?\n---/);
	const block = match?.[1] ?? '';
	const title = block.match(/^title:\s*["']?(.+?)["']?\s*$/m)?.[1]?.trim() ?? '';
	const label = block.match(/^\s+label:\s*["']?(.+?)["']?\s*$/m)?.[1]?.trim();
	const order = Number(block.match(/^\s+order:\s*(-?\d+)\s*$/m)?.[1] ?? Number.MAX_SAFE_INTEGER);
	return { title, label, order };
}

function indexFile(dirPath: string): string | undefined {
	return ['index.mdx', 'index.md']
		.map((name) => path.join(dirPath, name))
		.find((file) => fs.existsSync(file));
}

function collect(directory: string): Ranked[] {
	const dirPath = path.join(docsRoot, directory);
	const ranked: Ranked[] = [];

	for (const entry of fs.readdirSync(dirPath, { withFileTypes: true })) {
		if (entry.name.startsWith('.')) continue;

		if (entry.isDirectory()) {
			const index = indexFile(path.join(dirPath, entry.name));
			if (!index) continue;
			const fm = readFrontmatter(index);
			const childDirectory = `${directory}/${entry.name}`;
			const children = collect(childDirectory)
				.filter((child) => !child.isIndex)
				.sort(byOrder)
				.map((child) => child.item);
			ranked.push({
				order: fm.order,
				slug: childDirectory,
				isIndex: false,
				item: {
					label: fm.label || fm.title || entry.name,
					items: [{ slug: childDirectory, label: fm.title }, ...children],
				},
			});
			continue;
		}

		if (!entry.name.endsWith('.md') && !entry.name.endsWith('.mdx')) continue;
		const base = entry.name.replace(/\.mdx?$/, '');
		const fm = readFrontmatter(path.join(dirPath, entry.name));
		const isIndex = base === 'index';
		ranked.push({
			order: fm.order,
			slug: isIndex ? directory : `${directory}/${base}`,
			isIndex,
			item: { slug: isIndex ? directory : `${directory}/${base}` },
		});
	}

	return ranked;
}

function byOrder(a: Ranked, b: Ranked): number {
	if (a.order !== b.order) return a.order - b.order;
	return a.slug < b.slug ? -1 : a.slug > b.slug ? 1 : 0;
}

/** Sidebar group for a tab. Home holds the landing page. Other tabs follow their folder. */
export function tabSidebar(tab: Tab) {
	if (!tab.directory) return { label: tab.label, items: ['index'] };
	return {
		label: tab.label,
		items: collect(tab.directory)
			.sort(byOrder)
			.map((entry) => entry.item),
	};
}
